    private final java.util.Map<Integer, java.util.LinkedHashSet<Integer>> freqMap = new java.util.HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        int[] info = keyMap.get(key);
        if (info == null) {
            return -1;
        }
        increaseFrequency(key, info);
        return info[0];
    }

    public void put(int key, int value) {
        if (capacity == 0) {
            return;
        }
        int[] info = keyMap.get(key);
        if (info != null) {
            info[0] = value;
            increaseFrequency(key, info);
            return;
        }
        if (keyMap.size() == capacity) {
