            }
            keyMap.remove(victim);
        }
        keyMap.put(key, new int[]{value, 1});
        freqMap.computeIfAbsent(1, f -> new java.util.LinkedHashSet<>()).add(key);
        minFreq = 1;
    }

    private void increaseFrequency(int key, int[] info) {
