class LFUCache {
    private static class Node {
        int key, value, freq = 1;
        Node prev, next;
        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private static class DList {
        Node head = new Node(0, 0);
        Node tail = new Node(0, 0);
        int size;
        DList() {
            head.next = tail;
            tail.prev = head;
        }
        void addLast(Node node) {
            node.prev = tail.prev;
            node.next = tail;
            tail.prev.next = node;
            tail.prev = node;
            size++;
        }
        void remove(Node node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
            size--;
        }
        Node removeFirst() {
            Node node = head.next;
            remove(node);
            return node;
        }
    }

    private final int capacity;
    private int minFreq;
    private final java.util.Map<Integer, Node> nodes = new java.util.HashMap<>();
    private final java.util.Map<Integer, DList> lists = new java.util.HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        Node node = nodes.get(key);
        if (node == null) {
            return -1;
        }
        promote(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) {
            return;
        }
        Node node = nodes.get(key);
        if (node != null) {
            node.value = value;
            promote(node);
            return;
        }
        if (nodes.size() == capacity) {
            Node victim = lists.get(minFreq).removeFirst();
            nodes.remove(victim.key);
        }
        Node fresh = new Node(key, value);
        nodes.put(key, fresh);
        lists.computeIfAbsent(1, f -> new DList()).addLast(fresh);
        minFreq = 1;
    }

    private void promote(Node node) {
        int oldFreq = node.freq;
        DList oldList = lists.get(oldFreq);
        oldList.remove(node);
        if (oldList.size == 0 && minFreq == oldFreq) {
            minFreq++;
        }
        node.freq++;
        lists.computeIfAbsent(node.freq, f -> new DList()).addLast(node);
    }
}

class LFUCache {
    private static class Entry {
        int key, value, freq = 1;
        Entry(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private static class Bucket {
        int freq;
        java.util.LinkedHashSet<Integer> keys = new java.util.LinkedHashSet<>();
        Bucket prev, next;
        Bucket(int freq) {
            this.freq = freq;
        }
    }

    private final int capacity;
    private final java.util.Map<Integer, Entry> entries = new java.util.HashMap<>();
    private final java.util.Map<Integer, Bucket> buckets = new java.util.HashMap<>();
    private final Bucket head = new Bucket(0);
    private final Bucket tail = new Bucket(0);

    public LFUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Entry entry = entries.get(key);
        if (entry == null) {
            return -1;
        }
        touch(entry);
        return entry.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) {
            return;
        }
        Entry entry = entries.get(key);
        if (entry != null) {
            entry.value = value;
            touch(entry);
            return;
        }
        if (entries.size() == capacity) {
            Bucket first = head.next;
            int victim = first.keys.iterator().next();
            first.keys.remove(victim);
            entries.remove(victim);
            if (first.keys.isEmpty()) {
                unlink(first);
            }
        }
        Entry fresh = new Entry(key, value);
        entries.put(key, fresh);
        Bucket bucket = buckets.get(1);
        if (bucket == null) {
            bucket = new Bucket(1);
            insertAfter(head, bucket);
        }
        bucket.keys.add(key);
    }

    private void touch(Entry entry) {
        Bucket oldBucket = buckets.get(entry.freq);
        oldBucket.keys.remove(entry.key);
        int nextFreq = entry.freq + 1;
        Bucket nextBucket = oldBucket.next;
        if (nextBucket == tail || nextBucket.freq != nextFreq) {
            nextBucket = new Bucket(nextFreq);
            insertAfter(oldBucket, nextBucket);
        }
        entry.freq = nextFreq;
        nextBucket.keys.add(entry.key);
        if (oldBucket.keys.isEmpty()) {
            unlink(oldBucket);
        }
    }

    private void insertAfter(Bucket previous, Bucket bucket) {
        bucket.prev = previous;
        bucket.next = previous.next;
        previous.next.prev = bucket;
        previous.next = bucket;
        buckets.put(bucket.freq, bucket);
    }

    private void unlink(Bucket bucket) {
        bucket.prev.next = bucket.next;
        bucket.next.prev = bucket.prev;
        buckets.remove(bucket.freq);
    }
}

class LFUCache {
    private static final int MAX_KEY = 100000;
    private final int capacity;
    private int size;
    private int minFreq;
    private final boolean[] present = new boolean[MAX_KEY + 1];
    private final int[] values = new int[MAX_KEY + 1];
    private final int[] freqs = new int[MAX_KEY + 1];
    private final java.util.Map<Integer, java.util.LinkedHashSet<Integer>> buckets = new java.util.HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        if (key < 0 || key > MAX_KEY || !present[key]) {
            return -1;
        }
        promote(key);
        return values[key];
    }

    public void put(int key, int value) {
        if (capacity == 0 || key < 0 || key > MAX_KEY) {
            return;
        }
        if (present[key]) {
            values[key] = value;
            promote(key);
            return;
        }
        if (size == capacity) {
            java.util.LinkedHashSet<Integer> keys = buckets.get(minFreq);
            int victim = keys.iterator().next();
            keys.remove(victim);
            if (keys.isEmpty()) {
                buckets.remove(minFreq);
            }
            present[victim] = false;
            size--;
        }
        present[key] = true;
        values[key] = value;
        freqs[key] = 1;
        buckets.computeIfAbsent(1, f -> new java.util.LinkedHashSet<>()).add(key);
        minFreq = 1;
        size++;
    }

    private void promote(int key) {
        int oldFreq = freqs[key];
        java.util.LinkedHashSet<Integer> keys = buckets.get(oldFreq);
        keys.remove(key);
        if (keys.isEmpty()) {
            buckets.remove(oldFreq);
            if (minFreq == oldFreq) {
                minFreq++;
            }
        }
        freqs[key] = oldFreq + 1;
        buckets.computeIfAbsent(oldFreq + 1, f -> new java.util.LinkedHashSet<>()).add(key);
    }
}
